// BMC The required keys must be present for every protocol; for `none`
// their values are the machine's identity in place of a BMC —
// `address` is `none://<mac>` and `credential_id` is the empty string.
type BMC struct {
	// Address Out-of-band management address (host or host:port); `none://<mac>` for protocol `none`, `fake://<name>` for the simulator.
	Address         string       `json:"address"`
	CredentialId    CredentialId `json:"credential_id"`
	FirmwareVersion *string      `json:"firmware_version,omitempty"`
	Model           *string      `json:"model,omitempty"`

	// Protocol `auto` probes Redfish first and falls back to IPMI.
	// `fake` selects the in-process simulator for development and testing.
	// `none` registers a machine without a BMC (docs/
	// 13-headless-design.md): identity is the NIC MAC carried in the
	// synthetic address `none://<mac>`; installs are driven over PXE with
	// the machine's own boot (Wake-on-LAN, graceful in-band reboot of an
	// installed system, or a manual power-on as the fallback). Out-of-band
	// actions (power, boot device, BIOS, drive erase) are unsupported on
	// `none` machines; `credential_id` must be empty.
	Protocol *BMCProtocol `json:"protocol,omitempty"`

	// Vendor Discovered values, filled by inventory probes.
	Vendor *string `json:"vendor,omitempty"`
}

